import {HOF} from './hof-layout.mjs';
import {exchangeInventory,trade,rest,capacity,weight} from './progression.mjs';
export const HAY_FIELD={x:-36,z:7,w:12,d:10,entry:{x:-28.8,z:7}};
export const POND_CAMP={x:33,z:-10,entry:{x:32,z:-9.5},tent:{x:36,z:-12}};
export const freshAlpLife=()=>({hayCutDay:0,hayTakenDay:0,hayCollected:0,carvings:0,roasted:0,hayStored:0,housed:{berta:false,lotti:false,goats:false,hens:false,jonny:false}});
export function validAlpLife(v,day){return v&&Number.isSafeInteger(v.hayCollected)&&v.hayCollected>=0&&v.hayCollected<=32&&(v.hayTakenDay!==v.hayCutDay||v.hayTakenDay===0||v.hayCollected===32)&&Number.isSafeInteger(v.hayStored)&&v.hayStored>=0&&v.hayStored<=100000&&v.housed&&Object.keys(v.housed).length===5&&['berta','lotti','goats','hens','jonny'].every(k=>typeof v.housed[k]==='boolean')&&['hayCutDay','hayTakenDay'].every(k=>Number.isSafeInteger(v[k])&&v[k]>=0&&v[k]<=day)&&v.hayTakenDay<=v.hayCutDay&&['carvings','roasted'].every(k=>Number.isSafeInteger(v[k])&&v[k]>=0&&v[k]<=1000000);}
const near=(s,p,region='alp')=>s.position.region===region&&!s.position.inside&&Math.hypot(s.position.x-p.x,s.position.z-p.z)<3;
export const hayCapacity=s=>s.estate.built.silo?256:64;
export function alpAction(s,id){const a=s.alpLife;
 if(id==='store-hay'||id==='take-hay'){if(!near(s,HOF.kiosk.entry))return{ok:false,message:'Gehe zum offenen Heuunterstand.'};const n=id==='store-hay'?Math.min(8,s.inventory.hay||0,Math.max(0,hayCapacity(s)-a.hayStored)):Math.min(4,a.hayStored);if(!n)return{ok:false,message:id==='store-hay'?(a.hayStored>=hayCapacity(s)?'Heulager voll. Baue das grosse Heulager aus.':'Mähe zuerst Gras und hole den Ballen am Feldrand.'):'Der Unterstand ist leer. Mähe die Heuwiese.'};if(id==='store-hay'&&a.hayStored+n>hayCapacity(s))return{ok:false,message:'Der Heuvorrat ist voll.'};const r=exchangeInventory(s,id==='store-hay'?{take:{hay:n}}:{give:{hay:n}});if(r.ok)a.hayStored+=id==='store-hay'?n:-n;return r.ok?{ok:true,message:n+' Portionen Heu '+(id==='store-hay'?'eingelagert.':'zum Füttern eingepackt.')}:r;}

 if(id==='cut'||id==='hay'){if(!near(s,HAY_FIELD.entry))return{ok:false,message:'Gehe an den Rand deiner Heuwiese.'};if(id==='cut'){if(!s.inventory.sickle)return{ok:false,message:'Hole dir zuerst die kostenlose Leihsichel am Feldrand.'};if(a.hayCutDay===s.day)return{ok:false,message:'Das Gras wächst nach einer Spielnacht nach.'};const r=exchangeInventory(s,{energy:s.estate.built.tools?2:5});if(!r.ok)return r;a.hayCutDay=s.day;a.hayCollected=0;return{ok:true,message:'Wiese gemäht. Der Heuballen wartet am Feldrand.'};}if(a.hayCutDay!==s.day||a.hayTakenDay===s.day)return{ok:false,message:'Hier liegt gerade kein frischer Heuballen.'};const n=Math.min(8,32-a.hayCollected,Math.max(0,capacity(s)-weight(s)));if(!n)return{ok:false,message:'Schaffe Platz im Rucksack oder lagere Heu im Unterstand ein.'};const r=exchangeInventory(s,{give:{hay:n}});if(r.ok){a.hayCollected+=n;if(a.hayCollected===32)a.hayTakenDay=s.day;}return r.ok?{ok:true,message:n+' Heu aufgenommen · '+(32-a.hayCollected)+' Portionen am Feldrand.'}:r;}
 if(id==='sickle'){if(!near(s,HAY_FIELD.entry))return{ok:false,message:'Die Leihsichel liegt am Feldrand.'};if(s.inventory.sickle)return{ok:false,message:'Du hast bereits eine Sichel.'};return exchangeInventory(s,{give:{sickle:1}});}
 if(!near(s,POND_CAMP.entry))return{ok:false,message:'Gehe zuerst zum Lagerplatz am kleinen See.'};
 if(id==='sleep')return rest(s,true,true);
 if(id==='carve'){const r=exchangeInventory(s,{take:{wood:1},give:{handle:1},energy:3});if(r.ok)a.carvings++;return r;}
 if(id==='roast'){const r=exchangeInventory(s,{take:{marshmallow:1},give:{roastedMarshmallow:1},energy:1});if(r.ok)a.roasted++;return r;}
 return{ok:false,message:'Unbekannte Aktion.'};
}
export function buyVillageFodder(s,id){if(!near(s,{x:14,z:-5.5},'village')||!['hay','grain','marshmallow'].includes(id))return{ok:false,message:'Futter erhältst du beim Dorfladen.'};return trade(s,id,'buy',true);}
export function createAlpLifePanels({getState,capture,show,changed,openActivity=()=>{}}){
 const $=id=>document.getElementById(id);function run(id,next){capture();const r=alpAction(getState(),id);if(r.ok)changed();next(r.message|| (r.ok?'Erledigt.':''));}
 function field(m=''){capture();const s=getState(),a=s.alpLife;show('<span class="eyebrow">DEINE HEUWIESE · TAG '+s.day+'</span><h2>Gras für die Tiere</h2><div class="compact-work-status"><label>Mähen <b>'+(a.hayCutDay===s.day?'✓ Fertig':'0 / 6 · 0 %')+'</b><progress max="6" value="'+(a.hayCutDay===s.day?6:0)+'" aria-label="Mähfortschritt"></progress></label><label>Heu eingesammelt <b>'+(a.hayCutDay===s.day?a.hayCollected:0)+' / 32</b><progress max="32" value="'+(a.hayCutDay===s.day?a.hayCollected:0)+'" aria-label="Heu eingesammelt"></progress></label></div><p role="status">'+m+'</p><p>Mit der Sichel mähen, dann den Ballen aufnehmen. Die 120 m² grosse Heuwiese liefert 32 Portionen pro Spieltag. Hole sie in tragbaren Bündeln und lagere sie im Unterstand ein. Nach einer Spielnacht wächst die Wiese nach. Körner für die Hühner erntest du am Kornfeld.</p><button id="hay-sickle" '+(s.inventory.sickle?'disabled':'')+'>Leihsichel nehmen · kostenlos</button><button id="hay-cut" '+(!s.inventory.sickle||a.hayCutDay===s.day?'disabled':'')+'>Mit der Sichel mähen · '+(s.estate.built.tools?2:5)+' Energie</button><button id="hay-take" '+(a.hayCutDay!==s.day||a.hayTakenDay===s.day?'disabled':'')+'>Heu holen · bis zu 8 von '+(a.hayCutDay===s.day?32-a.hayCollected:0)+' Portionen</button>');$('hay-sickle').onclick=()=>run('sickle',field);$('hay-cut').onclick=()=>action('cut');$('hay-take').onclick=()=>run('hay',field);}
 function shelter(m=''){capture();const s=getState();show('<span class="eyebrow">OFFENER HEUUNTERSTAND</span><h2>Dein Wintervorrat</h2><p role="status">'+m+'</p><p>Hier lagert dein selbst gemähtes Heu. Mähe die Heuwiese westlich vom Hof, hole den Ballen und bring ihn hierher.</p><p><b>'+s.alpLife.hayStored+' / '+hayCapacity(s)+' Portionen eingelagert</b> · '+(s.inventory.hay||0)+' im Rucksack</p><button id="hay-store">Bis zu 8 Heu einlagern</button><button id="hay-fetch">Bis zu 4 Heu zum Füttern holen</button>');$('hay-store').onclick=()=>run('store-hay',shelter);$('hay-fetch').onclick=()=>run('take-hay',shelter);}
 function camp(m=''){capture();show('<span class="eyebrow">RUHEPLATZ AM KLEINEN SEE</span><h2>Hier darfst du einfach sein.</h2><p role="status">'+m+'</p><p>Ein trockenes Plätzchen, das Feuer und das Wasser. Das Zelt ist ein Schlafplatz. Für heute musst du nichts mehr schaffen.</p><button id="camp-roast">Marshmallows am Feuer rösten</button><button id="camp-grill">Gefangenen Fisch am Feuer rösten</button><button id="camp-sleep">Im Zelt schlafen · nächster Spieltag</button>');$('camp-roast').onclick=()=>openActivity('roast');$('camp-grill').onclick=()=>openActivity('grill');$('camp-sleep').onclick=()=>run('sleep',camp);}
 function action(id){let progress=0,done=false;const title=id==='cut'?'Die Sichel durch das Gras ziehen':id==='carve'?'Den Holzstiel schnitzen':'Den Marshmallow über dem Feuer drehen';show('<span class="eyebrow">EGO-ANSICHT · '+title+'</span><h2>'+title+'</h2><div class="hands-scene '+id+'"><svg viewBox="0 0 600 300" role="img" aria-label="Blick auf deine Hände bei der Arbeit"><defs><linearGradient id="sleeve"><stop stop-color="#334e3a"/><stop offset="1" stop-color="#69805d"/></linearGradient><linearGradient id="timber"><stop stop-color="#a87542"/><stop offset="1" stop-color="#e3bc7e"/></linearGradient></defs><path fill="url(#sleeve)" d="M0 300L65 163 151 174 205 300M600 300L529 159 452 179 406 300"/><path fill="#c7926d" d="M65 165Q98 120 127 137L179 179Q185 210 158 220L103 199ZM529 161Q502 125 473 144L419 184Q410 214 443 222L501 195Z"/><path fill="url(#timber)" d="M145 175L458 149 463 174 153 201Z"/><path id="action-tool" fill="'+(id==='roast'?'#f5dfc6':'#c4c9c0')+'" d="'+(id==='roast'?'M296 111Q330 92 354 116L357 164Q330 181 299 161Z':id==='cut'?'M352 155Q355 25 210 23Q319 60 317 150Z':'M426 178L280 130 352 199Z')+'"/></svg></div><progress class="compact-work-bar" id="alp-action-progress" max="6" value="0" aria-label="Arbeitsfortschritt"></progress><p id="alp-action-hint">'+(id==='roast'?'Sechs ruhige Drehungen am Feuer.':'0 / 6 · 0 % · Sechs gleichmässige Bewegungen.')+'</p><button id="alp-action-step" class="primary">'+(id==='roast'?'Vorsichtig drehen':id==='cut'?'Sichel ziehen':'Span abziehen')+'</button><button id="alp-action-back">Abbrechen</button>');$('alp-action-step').onclick=()=>{if(done)return;progress++;$('alp-action-progress').value=progress;$('alp-action-hint').textContent=progress+' / 6 · '+Math.round(progress/6*100)+' %'+(progress===6?' · Fertig':'');$('action-tool')?.setAttribute('transform','rotate('+(progress%2?8:-5)+' 350 170)');if(progress===6){done=true;run(id,id==='cut'?field:camp);}};$('alp-action-back').onclick=id==='cut'?()=>field():()=>camp();}
 function shop(m=''){capture();show('<span class="eyebrow">DORFLADEN · FUTTER & VORRAT</span><h2>Nachschub für die Alp</h2><p role="status">'+m+'</p><button id="fodder-hay">Heu kaufen · CHF 0.90</button><button id="fodder-grain">Körner kaufen · CHF 0.80</button><button id="fodder-marshmallow">Marshmallow kaufen · CHF 1.20</button>');for(const id of ['hay','grain','marshmallow'])$('fodder-'+id).onclick=()=>{capture();const r=buyVillageFodder(getState(),id);if(r.ok)changed();shop(r.message);};}
 return{field,camp,shelter,shop};
}
